//! Lagoon: moonlit water under a star field. Raindrop rings spread and fade
//! on dark ripples, the moon glare widens toward the shore, reeds sway at the
//! bank and lotus pads drift with pulsing flowers.
use crate::_0_profile::measure_layer;
use crate::color::{darken, hsl_to_rgb, lerp_color, lighten};
use crate::opts::param_f32;
use crate::registry::{AnimKind, Mode, ModeFrame, Param};
use crate::types::{Cell, Grid};
use crossterm::style::Color;
use std::f32::consts::TAU;

pub(super) struct Lagoon;
pub(super) static MODE: Lagoon = Lagoon;

const NAME: &str = "lagoon";
const KNOBS: usize = 10;
const HELP: &str = "lagoon: moonlit water, rain rings, swaying reeds, drifting lotus [sky] [drops] [ripple] [moon] [glare] [shimmer] [reeds] [sway] [hue] [drift]";

const PARAMS: &[Param] = &[
    param!("SKY", "sky rows fraction", 0.1, 0.5, 0.3, 0.01),
    param!("DROPS", "raindrop density", 0.0, 1.0, 0.55, 0.05),
    param!("RIPPLE", "ring spread speed", 0.1, 2.0, 0.9, 0.05),
    param!("MOON", "moon column", 0.1, 0.9, 0.68, 0.01),
    param!("GLARE", "moon glare strength", 0.0, 2.0, 1.0, 0.05),
    param!("SHIMMER", "water shimmer", 0.0, 2.0, 1.0, 0.05),
    param!("REEDS", "reed density", 0.0, 1.0, 0.5, 0.05),
    param!("SWAY", "reed sway", 0.0, 2.0, 0.7, 0.05),
    param!("HUE", "water hue", 0.0, 360.0, 210.0, 1.0),
    param!("DRIFT", "lotus drift", 0.0, 1.0, 0.4, 0.05),
];

/// Water texture ramp, calm to stirred.
const WATER: [char; 7] = [' ', '.', '`', '~', '-', '=', 'o'];
/// Moon disc ramp, limb to core.
const MOON_RAMP: [char; 5] = ['.', 'o', 'O', '@', '*'];
/// Ripple ring marks.
const RING: [char; 2] = ['~', '='];
/// Star glyphs.
const STAR: [char; 2] = ['.', '*'];
const L_SKY: u64 = 0x21;
const L_WATER: u64 = 0x22;
const L_RIP: u64 = 0x23;
const L_REED: u64 = 0x24;
const L_LOTUS: u64 = 0x25;
const L_FLORA: u64 = 0x26;
/// Parallel row threshold; below this a single thread paints.
const PARALLEL_MIN_CELLS: usize = 20_480;
const CYCLE: f32 = 3.0;

impl Mode for Lagoon {
    fn name(&self) -> &'static str {
        NAME
    }
    fn help(&self) -> &'static str {
        HELP
    }
    fn animation(&self) -> AnimKind {
        AnimKind::Iterate
    }
    fn params(&self) -> &'static [Param] {
        PARAMS
    }
    fn render(&self, frame: &mut ModeFrame<'_>) {
        let p: [f32; KNOBS] = std::array::from_fn(|i| {
            let param = &PARAMS[i];
            let value = frame
                .args
                .get(i + 4)
                .and_then(|v| v.parse::<f32>().ok())
                .or_else(|| frame.param_values.and_then(|v| v.get(i)).copied())
                .unwrap_or_else(|| param_f32(param.key, param.default));
            if value.is_finite() {
                value.clamp(param.min, param.max)
            } else {
                param.default
            }
        });
        draw(frame, &p);
    }
}

/// Splitmix64 over (seed, layer, index, slot); no rng stream is consumed.
#[inline]
fn hash(seed: u64, layer: u64, index: u64, slot: u64) -> u64 {
    let mut z = seed
        ^ layer.wrapping_mul(0x9E37_79B9_7F4A_7C15)
        ^ index.wrapping_mul(0xD1B5_4A32_D192_ED03)
        ^ slot.wrapping_mul(0xC2B2_AE3D_27D4_EB4F);
    z ^= z >> 30;
    z = z.wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z ^= z >> 27;
    z = z.wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

#[inline]
fn unit(h: u64) -> f32 {
    (h >> 40) as f32 * (1.0 / 16_777_216.0)
}

#[inline]
fn smoothstep(t: f32) -> f32 {
    let t = t.clamp(0.0, 1.0);
    t * t * (3.0 - 2.0 * t)
}

/// Value noise on a coarse lattice; lattice points derive from the seed.
#[inline]
fn noise(seed: u64, layer: u64, u: f32, v: f32) -> f32 {
    let iu = u.floor() as u64;
    let iv = v.floor() as u64;
    let fu = smoothstep(u - u.floor());
    let fv = smoothstep(v - v.floor());
    let n = |a: u64, b: u64| unit(hash(seed, layer, a, b));
    let top = n(iu, iv) * (1.0 - fu) + n(iu + 1, iv) * fu;
    let bot = n(iu, iv + 1) * (1.0 - fu) + n(iu + 1, iv + 1) * fu;
    top * (1.0 - fv) + bot * fv
}

/// One frame's resolved geometry and palette.
struct Look {
    seed: u64,
    time: f32,
    horizon: f32,
    w: f32,
    h: f32,
    mx: f32,
    my: f32,
    moon_r: f32,
    drops: usize,
    ripple: f32,
    glare: f32,
    shimmer: f32,
    reeds: usize,
    sway: f32,
    hue: f32,
    drift: f32,
    moon_color: Color,
    star_color: Color,
    water_base: Color,
    reed_color: Color,
    pad_color: Color,
    flower_color: Color,
}

impl Look {
    fn new(seed: u64, w: usize, h: usize, palette: &[Color; 5], time: f32, p: &[f32; KNOBS]) -> Self {
        let horizon = (p[0] * h as f32).round().max(1.0);
        let mx = p[3].clamp(0.05, 0.95) * w as f32;
        let my = horizon * 0.45;
        Look {
            seed,
            time,
            horizon,
            w: w as f32,
            h: h as f32,
            mx,
            my,
            moon_r: (horizon * 0.35).max(1.6),
            drops: (p[1] * 11.0).round().max(0.0) as usize,
            ripple: p[2],
            glare: p[4],
            shimmer: p[5],
            reeds: (p[6] * 12.0).round().max(0.0) as usize,
            sway: p[7],
            hue: p[8],
            drift: p[9],
            moon_color: lighten(palette[4], 20),
            star_color: lerp_color(palette[4], palette[3], 0.4),
            water_base: darken(palette[1], 25),
            reed_color: hsl_to_rgb(115.0, 0.45, 0.28),
            pad_color: hsl_to_rgb(100.0, 0.5, 0.3),
            flower_color: lighten(palette[3], 15),
        }
    }

    /// Water light level at a cell before ripples: shimmer plus moon glare.
    #[inline]
    fn water_level(&self, x: f32, y: f32) -> f32 {
        let depth = y - self.horizon;
        let n = noise(self.seed, L_WATER, x * 0.3, (depth - self.time * 1.5) * 0.3);
        let mut level = (n - 0.45).max(0.0) * 0.6 * self.shimmer;
        let hw = 1.0 + depth * 0.45;
        let d = (x - self.mx) / hw;
        level += (-d * d).exp() * 0.45 * self.glare;
        level
    }

    #[inline]
    fn water_cell(&self, level: f32, x: f32, y: f32) -> Cell {
        let depth = (y - self.horizon).max(0.0);
        let hue = (self.hue + depth * 0.7) as f64;
        let lit = (0.05 + level * 0.22).clamp(0.03, 0.4) as f64;
        let fg = hsl_to_rgb(hue, 0.55, lit);
        let bg = hsl_to_rgb(hue, 0.45, (lit * 0.45).clamp(0.02, 0.2));
        let idx = (level * WATER.len() as f32) as usize;
        Cell::with_bg(WATER[idx.min(WATER.len() - 1)], fg, bg)
    }
}

#[inline(always)]
fn each_row<T: Send, F>(buf: &mut [T], w: usize, h: usize, row: F)
where
    F: Fn((usize, &mut [T])) + Sync + Send,
{
    if w == 0 {
        return;
    }
    if w * h >= PARALLEL_MIN_CELLS {
        buf.par_chunks_mut(w).enumerate().with_min_len(8).for_each(row);
    } else {
        buf.chunks_mut(w).enumerate().for_each(row);
    }
}

use rayon::prelude::*;

fn draw(frame: &mut ModeFrame<'_>, p: &[f32; KNOBS]) {
    let w = frame.width;
    let h = frame.height;
    let look = Look::new(frame.seed, w, h, frame.palette, frame.time, p);
    measure_layer(NAME, "sky", || paint_sky(frame.grid, w, h, &look));
    measure_layer(NAME, "water", || paint_water(frame.grid, w, h, &look));
    measure_layer(NAME, "ripples", || paint_ripples(frame.grid, w, h, &look));
    measure_layer(NAME, "reeds", || paint_reeds(frame.grid, w, h, &look));
    measure_layer(NAME, "lotus", || paint_lotus(frame.grid, w, h, &look));
}

/// Stars, moon disc and its dark limb over the sky rows.
fn paint_sky(grid: &mut Grid, w: usize, h: usize, look: &Look) {
    let rows = grid.len().min(h);
    let top = look.horizon as usize;
    let sky = &mut grid[..rows.min(top.max(1))];
    let paint = |(y, row): (usize, &mut Vec<Cell>)| {
        let yf = y as f32;
        let night = hsl_to_rgb(look.hue as f64 * 0.5, 0.4, (0.04 + yf * 0.01) as f64);
        for (x, cell) in row.iter_mut().enumerate().take(w) {
            let xf = x as f32;
            let dx = xf - look.mx;
            let dy = yf - look.my;
            let dist = (dx * dx + dy * dy).sqrt();
            // Moon disc with an offset dark limb for the crescent.
            let limb = ((dx - look.moon_r * 0.55).powi(2) + dy * dy).sqrt();
            let mut ch = ' ';
            let mut fg = look.moon_color;
            if dist < look.moon_r {
                let core = 1.0 - dist / look.moon_r;
                if limb < look.moon_r {
                    fg = darken(look.moon_color, 55);
                    ch = 'o';
                } else {
                    let idx = (core * MOON_RAMP.len() as f32) as usize;
                    ch = MOON_RAMP[idx.min(MOON_RAMP.len() - 1)];
                }
            } else {
                // Stars twinkle on their own phases.
                let present = unit(hash(look.seed, L_SKY, x as u64, (y as u64) * 4)) < 0.14;
                if present {
                    let phase = unit(hash(look.seed, L_SKY, x as u64, (y as u64) * 4 + 1)) * TAU;
                    let tw = 0.55 + 0.45 * (look.time * 1.4 + phase).sin();
                    let bright = unit(hash(look.seed, L_SKY, x as u64, (y as u64) * 4 + 2)) < 0.2;
                    ch = STAR[(bright && tw > 0.7) as usize];
                    fg = if bright && tw > 0.7 {
                        lighten(look.star_color, 25)
                    } else {
                        look.star_color
                    };
                }
            }
            *cell = Cell::with_bg(ch, fg, night);
        }
    };
    if w * top >= PARALLEL_MIN_CELLS {
        sky.par_iter_mut().enumerate().with_min_len(8).for_each(paint);
    } else {
        sky.iter_mut().enumerate().for_each(paint);
    }
}

/// Dark rippling water with the widening moon glare column.
fn paint_water(grid: &mut Grid, w: usize, h: usize, look: &Look) {
    let rows = grid.len().min(h);
    let first = (look.horizon as usize).min(rows);
    let pond = &mut grid[first..rows];
    let paint = |(k, row): (usize, &mut Vec<Cell>)| {
        let y = (first + k) as f32;
        for (x, cell) in row.iter_mut().enumerate().take(w) {
            let level = look.water_level(x as f32, y);
            *cell = look.water_cell(level, x as f32, y);
        }
    };
    if w * (rows - first) >= PARALLEL_MIN_CELLS {
        pond.par_iter_mut().enumerate().with_min_len(8).for_each(paint);
    } else {
        pond.iter_mut().enumerate().for_each(paint);
    }
}

/// Raindrop rings: each drop spreads, fades and respawns on its own phase.
fn paint_ripples(grid: &mut Grid, w: usize, h: usize, look: &Look) {
    if look.drops == 0 {
        return;
    }
    let rows = grid.len().min(h);
    let first = (look.horizon as usize).min(rows);
    for i in 0..look.drops {
        let dx = unit(hash(look.seed, L_RIP, i as u64, 0)) * look.w;
        let dy = look.horizon + unit(hash(look.seed, L_RIP, i as u64, 1)) * (look.h - look.horizon - 1.0) + 0.5;
        let off = unit(hash(look.seed, L_RIP, i as u64, 2)) * CYCLE;
        let prog = ((look.time * look.ripple + off) % CYCLE) / CYCLE;
        let radius = prog * 7.0;
        let fade = 1.0 - prog;
        if fade <= 0.0 {
            continue;
        }
        let r0 = radius - 1.0;
        let r1 = radius + 1.0;
        let y0 = (dy + r0).max(look.horizon) as usize;
        let y1 = ((dy + r1) as usize).min(rows - 1);
        let x0 = (dx - r1).max(0.0) as usize;
        let x1 = ((dx + r1) as usize).min(w.saturating_sub(1));
        let hue = look.hue;
        let band = 0.85;
        for y in y0..=y1 {
            let row = &mut grid[y];
            for x in x0..=x1 {
                let ddx = x as f32 - dx;
                let ddy = y as f32 - dy;
                let dist = (ddx * ddx * 0.6 + ddy * ddy).sqrt();
                let near = 1.0 - ((dist - radius) / band).abs();
                if near <= 0.0 {
                    continue;
                }
                let bump = smoothstep(near) * fade * 0.55;
                let level = look.water_level(x as f32, y as f32) + bump;
                let depth = (y as f32 - look.horizon).max(0.0);
                let lit = (0.08 + level * 0.26).clamp(0.04, 0.5) as f64;
                let fg = hsl_to_rgb((hue + depth * 0.7) as f64, 0.5, lit);
                let idx = (level * WATER.len() as f32) as usize;
                let mut ch = WATER[idx.min(WATER.len() - 1)];
                if near > 0.55 {
                    ch = RING[(fade > 0.5) as usize];
                }
                row[x] = Cell::with_bg(ch, fg, row[x].bg);
            }
        }
    }
}

/// Reeds rooted at the bank, bending with the wind on their own phases.
fn paint_reeds(grid: &mut Grid, w: usize, h: usize, look: &Look) {
    if look.reeds == 0 {
        return;
    }
    let rows = grid.len().min(h);
    for i in 0..look.reeds {
        let x = unit(hash(look.seed, L_REED, i as u64, 0)) * look.w;
        let height = 2.0 + unit(hash(look.seed, L_REED, i as u64, 1)) * 4.5;
        let phase = unit(hash(look.seed, L_REED, i as u64, 2)) * TAU;
        let bend = (look.time * look.sway * 1.1 + phase).sin();
        let top = (h as f32 - height).ceil().max(look.horizon + 1.0) as usize;
        let tint = unit(hash(look.seed, L_REED, i as u64, 3)) * 20.0;
        for k in 0..(h - top).min(height as usize + 1) {
            let y = h - 1 - k;
            if y < first_row(look) {
                break;
            }
            let frac = k as f32 / height.max(1.0);
            let xo = (x + bend * frac * frac * 1.6).round() as isize;
            if xo < 0 || xo >= w as isize {
                continue;
            }
            let tip = frac > 0.7;
            let ch = if tip { '"' } else { '|' };
            let fg = hsl_to_rgb((115.0 + tint) as f64, 0.45, (0.22 + frac * 0.12) as f64);
            grid[y][xo as usize] = Cell::with_bg(ch, fg, grid[y][xo as usize].bg);
        }
    }
}

/// Water line the reeds must not cross above.
#[inline]
fn first_row(look: &Look) -> usize {
    look.horizon as usize
}

/// Lotus pads drifting on the water, flowers pulsing open and shut.
fn paint_lotus(grid: &mut Grid, w: usize, h: usize, look: &Look) {
    let count = (1.0 + look.drift * 5.0).round() as usize;
    let rows = grid.len().min(h);
    for i in 0..count {
        let ux = unit(hash(look.seed, L_LOTUS, i as u64, 0));
        let vy = 0.15 + unit(hash(look.seed, L_LOTUS, i as u64, 1)) * 0.8;
        let y = (look.horizon + vy * (look.h - look.horizon - 1.0)).round();
        let phase = unit(hash(look.seed, L_LOTUS, i as u64, 2)) * TAU;
        let x = (ux * look.w + (look.time * look.drift * 1.3 + phase).sin() * 2.5)
            .rem_euclid(look.w)
            .round() as usize;
        if y as usize >= rows || x >= w {
            continue;
        }
        let open = 0.5 + 0.5 * (look.time * 0.9 + phase).sin();
        let pad = Cell::with_bg('o', look.pad_color, grid[y as usize][x].bg);
        grid[y as usize][x] = pad;
        if open > 0.55 {
            let lit = (0.3 + open * 0.3) as f64;
            let fg = hsl_to_rgb(look.hue as f64 * 0.35 + 320.0, 0.6, lit);
            let ch = if open > 0.8 { '*' } else { '+' };
            grid[y as usize][x] = Cell::with_bg(ch, fg, grid[y as usize][x].bg);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::render::grid_to_plain;
    use rand::{rngs::StdRng, SeedableRng};

    fn knobs() -> Vec<f32> {
        PARAMS.iter().map(|p| p.default).collect()
    }

    fn frame(w: usize, h: usize, seed: u64, time: f32, values: &[f32]) -> Grid {
        let mut grid = vec![vec![Cell::blank(); w]; h];
        let palette = crate::color::make_palette(seed);
        let mut rng = StdRng::seed_from_u64(seed);
        MODE.render(&mut ModeFrame {
            grid: &mut grid,
            width: w,
            height: h,
            seed,
            palette: &palette,
            rng: &mut rng,
            time,
            args: &[],
            param_values: Some(values),
        });
        grid
    }

    fn text(grid: &Grid) -> String {
        grid_to_plain(grid).join("\n")
    }

    #[test]
    fn lagoon_seed42() {
        insta::assert_snapshot!("lagoon_80x24", text(&frame(80, 24, 42, 0.0, &knobs())));
    }

    #[test]
    fn lagoon_seed42_t6() {
        insta::assert_snapshot!("lagoon_80x24_t6", text(&frame(80, 24, 42, 6.0, &knobs())));
    }

    #[test]
    fn deterministic_and_seed_sensitive() {
        let k = knobs();
        assert_eq!(text(&frame(90, 30, 42, 0.0, &k)), text(&frame(90, 30, 42, 0.0, &k)));
        assert_ne!(text(&frame(90, 30, 42, 0.0, &k)), text(&frame(90, 30, 7, 0.0, &k)));
    }

    #[test]
    fn time_moves_the_water() {
        let k = knobs();
        assert_ne!(text(&frame(90, 30, 42, 0.0, &k)), text(&frame(90, 30, 42, 4.0, &k)));
    }

    #[test]
    fn drops_change_the_pond() {
        let mut k = knobs();
        let a = text(&frame(90, 30, 42, 0.0, &k));
        k[1] = 1.0;
        assert_ne!(a, text(&frame(90, 30, 42, 0.0, &k)));
    }

    #[test]
    fn frame_cost() {
        let (w, h) = (200usize, 60usize);
        let k = knobs();
        let mut worst = 0.0f64;
        let start = std::time::Instant::now();
        for f in 0..100 {
            let t0 = std::time::Instant::now();
            frame(w, h, 42, f as f32 * 0.05, &k);
            worst = worst.max(t0.elapsed().as_secs_f64() * 1000.0);
        }
        let avg = start.elapsed().as_secs_f64() * 1000.0 / 100.0;
        eprintln!("lagoon frame_cost 200x60: avg {:.3} ms, worst {:.3} ms", avg, worst);
        if !cfg!(debug_assertions) {
            assert!(avg < 6.0, "avg frame {:.3} ms", avg);
        }
    }
}
